#include <stdio.h>
#include <stdlib.h>

typedef struct DNode { int data; struct DNode *prev, *next; } DNode;

DNode *push_back(DNode *head, int v, DNode **tail_out) {
    DNode *n = malloc(sizeof(DNode));
    n->data = v; n->next = NULL;
    if (!head) { n->prev = NULL; *tail_out = n; return n; }
    DNode *t = *tail_out;
    t->next = n; n->prev = t; *tail_out = n;
    return head;
}

/* 核心：已知节点指针即可 O(1) 摘除（这是单链表做不到的） */
void unlink_node(DNode **head, DNode **tail, DNode *target) {
    if (target->prev) target->prev->next = target->next;
    else *head = target->next;                 /* 是头节点 */
    if (target->next) target->next->prev = target->prev;
    else *tail = target->prev;                 /* 是尾节点 */
    free(target);
}

void print_list(DNode *h) {
    printf("正向: ");
    for (DNode *p = h; p; p = p->next) printf("%d%s", p->data, p->next ? " <-> " : "");
    printf("\n");
}

int main(void) {
    DNode *head = NULL, *tail = NULL;
    for (int i = 1; i <= 4; i++) head = push_back(head, i * 10, &tail);
    print_list(head);
    unlink_node(&head, &tail, head->next);      /* 摘除 20（已知指针） */
    print_list(head);
    printf("摘除任意已知节点都是 O(1)：只需改 prev/next 两个指针\n");
    return 0;
}
